        assert(index < num());
        this->entity_ids()[index] = new_entity_ids;
        this->view_locations().set(index, new_locations);
        this->view_rotations().set(index, new_rotations);
        this->fighter_spawn_timers()[index] = new_fighter_spawn_timers;
