static_assert(ioj::soa_storage_detail::validate_compact_view<CapitalEntityDataView>());

/* **************************************** */
// Owner
/* **************************************** */
// Columns:
// entity_ids: EntityId
// locations_xs: float
// locations_ys: float
// locations_zs: float
// rotations_pitches: float
// rotations_yaws: float
// rotations_rolls: float
// fighter_spawn_timers: float
// fighter_spawn_cooldowns: float
// teams: ::ioj::Team
// fighter_id_spans: ioj::sim::IndexSpan
// target_ids: EntityId
struct CapitalEntityData
    : protected ioj::native_soa::StorageState
    , ioj::native_soa::StorageOperations {
    using soa_schema = CapitalEntityDataSchema;
    using Operations = ioj::native_soa::StorageOperations;
    using Layout = CapitalEntityDataLayout;
    using size_type = Layout::size_type;
    using byte_size_type = Layout::byte_size_type;

    static constexpr auto capacity_granularity = Layout::capacity_granularity;
    static constexpr auto allocation_alignment = Layout::allocation_alignment;
    static constexpr auto capacity_block_bound = Layout::capacity_block_bound;
    static constexpr auto max_capacity = Layout::max_capacity;

    static constexpr auto layout_bytes(byte_size_type blocks) noexcept -> byte_size_type {
        return Layout::layout_bytes(blocks);
    }

    using View = CapitalEntityDataView;
    using ConstView = CapitalEntityDataConstView;

    /* **************************************** */
    // Lifetime
    /* **************************************** */
    CapitalEntityData() noexcept
        : CapitalEntityData{*std::pmr::get_default_resource()} {}
    explicit CapitalEntityData(std::pmr::memory_resource& resource) noexcept
        : resource_{&resource} {}
    auto get_memory_resource() const noexcept -> std::pmr::memory_resource* { return resource_; }
    ~CapitalEntityData() { Operations::release_storage(*this); }
    CapitalEntityData(CapitalEntityData const&) = delete;
    auto operator=(CapitalEntityData const&) -> CapitalEntityData& = delete;
    CapitalEntityData(CapitalEntityData&& other) noexcept
        : resource_{other.resource_} {
        Operations::take_storage(*this, other);
    }
    auto operator=(CapitalEntityData&& other) -> CapitalEntityData& {
        return Operations::move_assign(*this, other);
    }
  protected:
    template <typename Byte>
    struct DataPointers {
        template <typename T>
        using Element = std::conditional_t<std::is_const_v<Byte>, T const, T>;
        Element<EntityId>* entity_ids{};
        Element<float>* locations_xs{};
        Element<float>* locations_ys{};
        Element<float>* locations_zs{};
        Element<float>* rotations_pitches{};
        Element<float>* rotations_yaws{};
        Element<float>* rotations_rolls{};
        Element<float>* fighter_spawn_timers{};
        Element<float>* fighter_spawn_cooldowns{};
        Element<::ioj::Team>* teams{};
        Element<IndexSpan>* fighter_id_spans{};
        Element<EntityId>* target_ids{};
        auto operator+(size_type const offset) const noexcept -> DataPointers {
            if (entity_ids == nullptr) {
                return {};
            }
            return {entity_ids + offset,
                    locations_xs + offset,
                    locations_ys + offset,
                    locations_zs + offset,
                    rotations_pitches + offset,
                    rotations_yaws + offset,
                    rotations_rolls + offset,
                    fighter_spawn_timers + offset,
                    fighter_spawn_cooldowns + offset,
                    teams + offset,
                    fighter_id_spans + offset,
                    target_ids + offset};
        }
    };
  private:
    friend Operations;
    friend ::ioj::soa_storage_detail::StorageRequirements;
    /* **************************************** */
    // Column pointers
    /* **************************************** */
    template <typename Byte>
    static auto make_data_unchecked(Byte* const data, byte_size_type const blocks) noexcept
        -> DataPointers<Byte> {
        ioj::native_soa::LayoutCursor cursor{blocks};
        return {cursor.column_pointer(data, Layout::columns.EntityIdsColumn),
                cursor.column_pointer(data, Layout::columns.Locations.XsColumn),
                cursor.column_pointer(data, Layout::columns.Locations.YsColumn),
                cursor.column_pointer(data, Layout::columns.Locations.ZsColumn),
                cursor.column_pointer(data, Layout::columns.Rotations.PitchesColumn),
                cursor.column_pointer(data, Layout::columns.Rotations.YawsColumn),
                cursor.column_pointer(data, Layout::columns.Rotations.RollsColumn),
                cursor.column_pointer(data, Layout::columns.FighterSpawnTimersColumn),
                cursor.column_pointer(data, Layout::columns.FighterSpawnCooldownsColumn),
                cursor.column_pointer(data, Layout::columns.TeamsColumn),
                cursor.column_pointer(data, Layout::columns.FighterIdSpansColumn),
                cursor.column_pointer(data, Layout::columns.TargetIdsColumn)};
    }

    /* **************************************** */
    // Typed mutations and growth
    /* **************************************** */
    void default_construct_columns(size_type const first, size_type const count) {
        using ioj::native_soa::default_construct_n;
        auto const columns{make_data_unchecked(data_, capacity_blocks()) + first};
        default_construct_n(columns.entity_ids, count);
        default_construct_n(columns.locations_xs, count);
        default_construct_n(columns.locations_ys, count);
        default_construct_n(columns.locations_zs, count);
        default_construct_n(columns.rotations_pitches, count);
        default_construct_n(columns.rotations_yaws, count);
        default_construct_n(columns.rotations_rolls, count);
        default_construct_n(columns.fighter_spawn_timers, count);
        default_construct_n(columns.fighter_spawn_cooldowns, count);
        default_construct_n(columns.teams, count);
        default_construct_n(columns.fighter_id_spans, count);
        default_construct_n(columns.target_ids, count);
    }
    template <bool Overlapping, typename Byte>
    static void transfer_columns(DataPointers<std::byte> const& destination,
                                 DataPointers<Byte> const& source,
                                 size_type count) {
        auto transfer = [count](auto* dst, auto const* src) {
            ioj::native_soa::transfer_n<Overlapping>(dst, src, count);
        };
        transfer(destination.entity_ids, source.entity_ids);
        transfer(destination.locations_xs, source.locations_xs);
        transfer(destination.locations_ys, source.locations_ys);
        transfer(destination.locations_zs, source.locations_zs);
        transfer(destination.rotations_pitches, source.rotations_pitches);
        transfer(destination.rotations_yaws, source.rotations_yaws);
        transfer(destination.rotations_rolls, source.rotations_rolls);
        transfer(destination.fighter_spawn_timers, source.fighter_spawn_timers);
        transfer(destination.fighter_spawn_cooldowns, source.fighter_spawn_cooldowns);
        transfer(destination.teams, source.teams);
        transfer(destination.fighter_id_spans, source.fighter_id_spans);
        transfer(destination.target_ids, source.target_ids);
    }
    template <typename Columns>
    static auto source_pointers(Columns const& source) -> DataPointers<std::byte const>
        requires ioj::soa_storage_detail::SoaSourceFor<Columns, CapitalEntityData, size_type>
    {
        using ioj::native_soa::source_data;
        auto const& locations_view{source.view_locations()};
        auto const& rotations_view{source.view_rotations()};
        return {source_data(source.entity_ids()),
                source_data(locations_view.xs()),
                source_data(locations_view.ys()),
                source_data(locations_view.zs()),
                source_data(rotations_view.pitches()),
                source_data(rotations_view.yaws()),
                source_data(rotations_view.rolls()),
                source_data(source.fighter_spawn_timers()),
                source_data(source.fighter_spawn_cooldowns()),
                source_data(source.teams()),
                source_data(source.fighter_id_spans()),
                source_data(source.target_ids())};
    }
  public:
    auto entity_ids(this auto& self) { return self.get_view().entity_ids(); }
    auto view_locations(this auto& self) { return self.get_view().view_locations(); }
    auto view_rotations(this auto& self) { return self.get_view().view_rotations(); }
    auto fighter_spawn_timers(this auto& self) { return self.get_view().fighter_spawn_timers(); }
    auto fighter_spawn_cooldowns(this auto& self) {
        return self.get_view().fighter_spawn_cooldowns();
    }
    auto teams(this auto& self) { return self.get_view().teams(); }
    auto fighter_id_spans(this auto& self) { return self.get_view().fighter_id_spans(); }
    auto target_ids(this auto& self) { return self.get_view().target_ids(); }
    void set(size_type index,
             EntityId const new_entity_ids,
             float const new_locations_xs,
             float const new_locations_ys,
             float const new_locations_zs,
             float const new_rotations_pitches,
             float const new_rotations_yaws,
             float const new_rotations_rolls,
             float const new_fighter_spawn_timers,
             float const new_fighter_spawn_cooldowns,
             ::ioj::Team const new_teams,
             IndexSpan const new_fighter_id_spans,
             EntityId const new_target_ids) {
        assert(index < num());
        get_view().entity_ids()[index] = new_entity_ids;
        get_view().view_locations().xs()[index] = new_locations_xs;
        get_view().view_locations().ys()[index] = new_locations_ys;
        get_view().view_locations().zs()[index] = new_locations_zs;
        get_view().view_rotations().pitches()[index] = new_rotations_pitches;
        get_view().view_rotations().yaws()[index] = new_rotations_yaws;
        get_view().view_rotations().rolls()[index] = new_rotations_rolls;
        get_view().fighter_spawn_timers()[index] = new_fighter_spawn_timers;
        get_view().fighter_spawn_cooldowns()[index] = new_fighter_spawn_cooldowns;
        get_view().teams()[index] = new_teams;
        get_view().fighter_id_spans()[index] = new_fighter_id_spans;
        get_view().target_ids()[index] = new_target_ids;
    }
    size_type add(EntityId const new_entity_ids,
                  float const new_locations_xs,
                  float const new_locations_ys,
                  float const new_locations_zs,
                  float const new_rotations_pitches,
                  float const new_rotations_yaws,
                  float const new_rotations_rolls,
                  float const new_fighter_spawn_timers,
                  float const new_fighter_spawn_cooldowns,
                  ::ioj::Team const new_teams,
                  IndexSpan const new_fighter_id_spans,
                  EntityId const new_target_ids) {
        auto const index{num()};
        add_uninitialised(1);
        set(index,
            new_entity_ids,
            new_locations_xs,
            new_locations_ys,
            new_locations_zs,
            new_rotations_pitches,
            new_rotations_yaws,
            new_rotations_rolls,
            new_fighter_spawn_timers,
            new_fighter_spawn_cooldowns,
            new_teams,
            new_fighter_id_spans,
            new_target_ids);
        return index;
    }
    void set(size_type index,
             EntityId const new_entity_ids,
             Vector3f const new_locations,
             Rotator3f const new_rotations,
             float const new_fighter_spawn_timers,
             float const new_fighter_spawn_cooldowns,
             ::ioj::Team const new_teams,
             IndexSpan const new_fighter_id_spans,
             EntityId const new_target_ids) {
        assert(index < num());
        get_view().entity_ids()[index] = new_entity_ids;
        get_view().view_locations().set(index, new_locations);
        get_view().view_rotations().set(index, new_rotations);
        get_view().fighter_spawn_timers()[index] = new_fighter_spawn_timers;
        get_view().fighter_spawn_cooldowns()[index] = new_fighter_spawn_cooldowns;
        get_view().teams()[index] = new_teams;
        get_view().fighter_id_spans()[index] = new_fighter_id_spans;
        get_view().target_ids()[index] = new_target_ids;
    }
    size_type add(EntityId const new_entity_ids,
                  Vector3f const new_locations,
                  Rotator3f const new_rotations,
                  float const new_fighter_spawn_timers,
                  float const new_fighter_spawn_cooldowns,
                  ::ioj::Team const new_teams,
                  IndexSpan const new_fighter_id_spans,
                  EntityId const new_target_ids) {
        auto const index{num()};
        add_uninitialised(1);
        set(index,
            new_entity_ids,
            new_locations,
            new_rotations,
            new_fighter_spawn_timers,
            new_fighter_spawn_cooldowns,
            new_teams,
            new_fighter_id_spans,
            new_target_ids);
        return index;
    }
    void apply_permutation(std::span<size_type> indices) {
        assert(indices.size() == num_);
        auto const columns{get_data()};
        ioj::apply_permutation(std::span{columns.entity_ids, num_}, indices);
        ioj::apply_permutation(std::span{columns.locations_xs, num_}, indices);
        ioj::apply_permutation(std::span{columns.locations_ys, num_}, indices);
        ioj::apply_permutation(std::span{columns.locations_zs, num_}, indices);
        ioj::apply_permutation(std::span{columns.rotations_pitches, num_}, indices);
        ioj::apply_permutation(std::span{columns.rotations_yaws, num_}, indices);
        ioj::apply_permutation(std::span{columns.rotations_rolls, num_}, indices);
        ioj::apply_permutation(std::span{columns.fighter_spawn_timers, num_}, indices);
        ioj::apply_permutation(std::span{columns.fighter_spawn_cooldowns, num_}, indices);
        ioj::apply_permutation(std::span{columns.teams, num_}, indices);
        ioj::apply_permutation(std::span{columns.fighter_id_spans, num_}, indices);
        ioj::apply_permutation(std::span{columns.target_ids, num_}, indices);
    }
  private:
    std::pmr::memory_resource* resource_{};
};
